#!/bin/bash
# Build Patrick OS.dmg via a single shell process. hdiutil errors with
# "Only one image can be created at a time" when invoked repeatedly from
# Node child_process under macOS sandbox; running the whole sequence
# inside one bash process sidesteps the lock entirely.
#
# This script is generated by build-dmg.js. Do not edit by hand.

set -euo pipefail

DIST_DIR="$1"
PAYLOAD_SIZE_BYTES="$2"

APP_BUNDLE="$DIST_DIR/Patrick OS.app"
STAGING_DIR="$DIST_DIR/dmg-staging"
DMG_FINAL="$DIST_DIR/Patrick OS-0.1.0.dmg"
TMP_DMG="/tmp/patrick-os-$$.dmg"
MOUNT_POINT="/tmp/patrick-os-dmg-mount-$$"

SIZE_MB=$(awk "BEGIN { printf \"%d\", ($PAYLOAD_SIZE_BYTES / 1024 / 1024) + 30 }")

echo "[build.sh] staging: $STAGING_DIR"
rm -rf "$STAGING_DIR"
mkdir -p "$STAGING_DIR"
ditto "$APP_BUNDLE" "$STAGING_DIR/Patrick OS.app"

echo "[build.sh] Applications symlink"
ln -sf /Applications "$STAGING_DIR/Applications"

echo "[build.sh] creating sparse RW dmg: $TMP_DMG ($SIZE_MB MB)"
rm -f "$TMP_DMG"
hdiutil create \
    -size "${SIZE_MB}m" \
    -fs HFS+ \
    -volname "Patrick OS 0.1.0" \
    -noanyowners \
    -o "$TMP_DMG"

echo "[build.sh] mounting: $MOUNT_POINT"
mkdir -p "$MOUNT_POINT"
hdiutil attach -nobrowse -mountpoint "$MOUNT_POINT" "$TMP_DMG"

echo "[build.sh] copying into mounted image"
ditto "$APP_BUNDLE" "$MOUNT_POINT/Patrick OS.app"
ln -sf /Applications "$MOUNT_POINT/Applications"

echo "[build.sh] detaching"
hdiutil detach "$MOUNT_POINT"
rmdir "$MOUNT_POINT" || true

echo "[build.sh] converting to UDZO: $DMG_FINAL"
rm -f "$DMG_FINAL"
hdiutil convert "$TMP_DMG" -format UDZO -o "$DMG_FINAL"

echo "[build.sh] cleaning up temp dmg"
rm -f "$TMP_DMG"

echo "[build.sh] done: $DMG_FINAL"
ls -la "$DMG_FINAL"